def check_ini(file_name, schema_file):
    # Open and read the JSON schema
    with open(schema_file, 'r') as schema_handle:
        rules = json.load(schema_handle)

    must_have_sections = rules.get('required_sections', [])

    # Load INI data
    parser = configparser.ConfigParser()
    try:
        parser.read(file_name)
    except configparser.Error as err:
        print(f"Failed to parse INI: {err}")
        return

    missing = []
    for req_section in must_have_sections:
        if req_section not in parser:
            missing.append(f"Section not found: {req_section}")

    if missing:
        for msg in missing:
            print(msg)
    else:
        print("INI file passes all checks.")

