class GradeSystem:
    def __init__(self, config_filepath):
        import json
        with open(config_filepath) as file:
            data = json.load(file)
        self.course_weights = data['weights']
        self.grade_scale = data['grading_scale']
        self.courses = list(self.course_weights.keys())

    def compute_weighted_score(self, course_name, marks):
        weights = self.course_weights[course_name]
        total = 0.0
        for component, weight in weights.items():
            total += marks.get(component, 0) * weight
        return total

    def convert_score_to_letter(self, numeric_score):
        for letter, threshold in sorted(self.grade_scale.items(), key=lambda x: -x[1]):
            if numeric_score >= threshold:
                return letter
        return 'F'

    def letter_to_gpa(self, grade_letter):
        gpa_map = {'A':4.0, 'B':3.0, 'C':2.0, 'D':1.0, 'F':0.0}
        return gpa_map.get(grade_letter, 0.0)

    def format_transcript(self, student_name, course_grades):
        output = [f"Report for {student_name}:"]
        output.append(f"{'Subject':<15}{'Result':<10}{'Mark':<10}")
        gpa_total = 0.0
        graded_courses = 0
        for subject, (score, grade) in course_grades.items():
            output.append(f"{subject:<15}{grade:<10}{score:<10.2f}")
            if grade:
                gpa_total += self.letter_to_gpa(grade)
                graded_courses += 1
        gpa = (gpa_total / graded_courses) if graded_courses > 0 else 0.0
        output.append(f"\nCumulative GPA: {gpa:.2f}")
        return '\n'.join(output)


